<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: #1a1a1a;
            font-family: Arial, sans-serif;
            color: #fff;
        }

        .container {
            text-align: center;
        }

        h1 {
            margin-bottom: 20px;
            font-size: 2em;
        }

        #score {
            font-size: 1.5em;
            margin-bottom: 20px;
            display: block;
        }

        #snake {
            border: 2px solid #fff;
            display: block;
            margin: 0 auto 20px;
            background: #0a0a0a;
        }

        .controls {
            display: flex;
            gap: 10px;
            justify-content: center;
            margin-top: 20px;
        }

        button {
            padding: 10px 20px;
            font-size: 1em;
            background: #2a2a2a;
            color: #fff;
            border: 1px solid #fff;
            cursor: pointer;
            border-radius: 4px;
            transition: background 0.2s;
        }

        button:hover {
            background: #3a3a3a;
        }

        button:active {
            background: #1a1a1a;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Snake Game</h1>
        <div id="score">Score: 0</div>
        <canvas id="snake" width="400" height="400"></canvas>
        <div class="controls">
            <button id="start">Start</button>
            <button id="pause">Pause</button>
            <button id="reset">Reset</button>
        </div>
    </div>

    <script>
        const GRID_SIZE = 20;
        const CELL_SIZE = 400 / GRID_SIZE;

        let gameState = {
            snake: [[10, 10], [9, 10], [8, 10]],
            direction: 'right',
            nextDirection: 'right',
            food: [15, 15],
            score: 0,
            alive: true,
            paused: false,
            gameLoopInterval: null
        };

        const canvas = document.getElementById('snake');
        const ctx = canvas.getContext('2d');

        function drawCell(x, y, color) {
            ctx.fillStyle = color;
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }

        function draw() {
            ctx.fillStyle = '#0a0a0a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            drawCell(gameState.food[0], gameState.food[1], '#ff4444');

            gameState.snake.forEach((segment, index) => {
                const color = index === 0 ? '#44ff44' : '#22aa22';
                drawCell(segment[0], segment[1], color);
            });

            ctx.strokeStyle = '#1a1a1a';
            ctx.lineWidth = 0.5;
            for (let i = 0; i <= GRID_SIZE; i++) {
                ctx.beginPath();
                ctx.moveTo(i * CELL_SIZE, 0);
                ctx.lineTo(i * CELL_SIZE, canvas.height);
                ctx.stroke();

                ctx.beginPath();
                ctx.moveTo(0, i * CELL_SIZE);
                ctx.lineTo(canvas.width, i * CELL_SIZE);
                ctx.stroke();
            }
        }

        function updateScore() {
            document.getElementById('score').textContent = `Score: ${gameState.score}`;
        }

        function generateFood() {
            let x, y, isOnSnake;
            do {
                x = Math.floor(Math.random() * GRID_SIZE);
                y = Math.floor(Math.random() * GRID_SIZE);
                isOnSnake = gameState.snake.some(segment => segment[0] === x && segment[1] === y);
            } while (isOnSnake);
            return [x, y];
        }

        function tick() {
            if (!gameState.alive) return;

            gameState.direction = gameState.nextDirection;

            const head = gameState.snake[0];
            let newHead;

            switch (gameState.direction) {
                case 'up':
                    newHead = [head[0], head[1] - 1];
                    break;
                case 'down':
                    newHead = [head[0], head[1] + 1];
                    break;
                case 'left':
                    newHead = [head[0] - 1, head[1]];
                    break;
                case 'right':
                    newHead = [head[0] + 1, head[1]];
                    break;
            }

            if (newHead[0] < 0 || newHead[0] >= GRID_SIZE || newHead[1] < 0 || newHead[1] >= GRID_SIZE) {
                gameState.alive = false;
                draw();
                return;
            }

            if (gameState.snake.some(segment => segment[0] === newHead[0] && segment[1] === newHead[1])) {
                gameState.alive = false;
                draw();
                return;
            }

            gameState.snake.unshift(newHead);

            if (newHead[0] === gameState.food[0] && newHead[1] === gameState.food[1]) {
                gameState.score++;
                updateScore();
                gameState.food = generateFood();
            } else {
                gameState.snake.pop();
            }

            draw();
        }

        function startGame() {
            if (gameState.gameLoopInterval) return;
            gameState.paused = false;
            gameState.gameLoopInterval = setInterval(() => {
                tick();
            }, 100);
        }

        function pauseGame() {
            gameState.paused = !gameState.paused;
            document.getElementById('pause').textContent = gameState.paused ? 'Resume' : 'Pause';
        }

        function resetGame() {
            clearInterval(gameState.gameLoopInterval);
            gameState.gameLoopInterval = null;
            gameState.snake = [[10, 10], [9, 10], [8, 10]];
            gameState.direction = 'right';
            gameState.nextDirection = 'right';
            gameState.food = generateFood();
            gameState.score = 0;
            gameState.alive = true;
            gameState.paused = false;
            document.getElementById('pause').textContent = 'Pause';
            updateScore();
            draw();
        }

        window.game = {
            w: GRID_SIZE,
            h: GRID_SIZE,
            reset: resetGame,
            tick: tick,
            setDir: (direction) => {
                const opposite = {
                    'up': 'down',
                    'down': 'up',
                    'left': 'right',
                    'right': 'left'
                };
                if (opposite[direction] !== gameState.direction) {
                    gameState.nextDirection = direction;
                }
            },
            setFood: (x, y) => {
                gameState.food = [x, y];
                draw();
            },
            snake: () => [...gameState.snake],
            food: () => [...gameState.food],
            alive: () => gameState.alive,
            score: () => gameState.score
        };

        document.addEventListener('keydown', (e) => {
            switch (e.key) {
                case 'ArrowUp':
                    window.game.setDir('up');
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    window.game.setDir('down');
                    e.preventDefault();
                    break;
                case 'ArrowLeft':
                    window.game.setDir('left');
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    window.game.setDir('right');
                    e.preventDefault();
                    break;
            }
        });

        document.getElementById('start').addEventListener('click', startGame);
        document.getElementById('pause').addEventListener('click', pauseGame);
        document.getElementById('reset').addEventListener('click', resetGame);

        resetGame();
    </script>
</body>
</html>
